package com.cyberencuentro.gamermode; import android.app.*; import android.content.Intent; import android.os.Build; import android.os.IBinder; class GamerModeService : Service() { override fun onBind(intent: Intent?): IBinder? = null; override fun onCreate() { super.onCreate(); if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) { val channel = NotificationChannel("gamer_channel", "Gamer Mode", NotificationManager.IMPORTANCE_LOW); (getSystemService(NotificationManager::class.java) as NotificationManager).createNotificationChannel(channel); val notif = Notification.Builder(this, "gamer_channel").setContentTitle("Cyber Gamer Activo").setContentText("Optimizando para Free Fire").setSmallIcon(android.R.drawable.ic_media_play).build(); startForeground(1, notif) } } }